body.usercss:

.signIconArea {
    display: flex;
    justify-content: center;
    align-items: center;
    border: 1px solid #b4b5bf;
    width: 200px;
    height: 200px;
    margin: 20px 20px;
}

.signAreaWrapper{
    display: flex;
    justify-content: center;
    align-items: center;
}

#ZRmVkNeSbHWkNecEsQ {
    height: 600px;
    display: flex;
    justify-content: center;
    align-items: center;
}

.signBtnArea{
    display: inline-block;
    height: 300px;
}

.buttton_area{
    display: flex;
    float: right;
    margin: 20px 20px;
}

.sepoa-button-item-type-modify{
    background-color: #307bee;
    border-color: #307bee;
    border-radius: 7px;
}

.sepoa-button-item-type-delete{
    background-color: #0000009c;
    border-color: #0000009c;
    border-radius: 7px;
}

.sepoa-button-item-label{
    color: #ffffff !important;;
}

.xi-plus:before{
    opacity: 0.5;
}

userscript.function:

var imageUrl = '';

doServiceAjax('sepoa.svc.contract.SepoaContractDigitalSign', 'CONNECTION', 'doQuery', '', function(so) {
    var sf = new SepoaFormater(so.result[0]);
    var sfList = sf.getArrayMap();
    var signAreaWrapper = document.createElement('div');
    signAreaWrapper.className = 'signAreaWrapper';

    this.sfList = sfList;

    for (var i = 0; i < 5; i++) {
        var result = sfList[i];
        var flag = false;
        if(typeof(result) == 'undefined'){
            //imageUrl = '/resource/design/imgs/common/FILE_ADD_IMG.png';
            imageUrl = '';
            flag = false;
        } else {
            if (sfList[i].ROOT_PATH_TYPE && sfList[i].DES_FILE_NAME) {
                imageUrl = '/SepoaImage.sux?mode=CUSTOM&METHOD=doImage&PROCESS_ID=sepoa.svc.contract.SepoaContractDigitalSign&signId=YDH_1&ROOT_PATH_TYPE=' + result.ROOT_PATH_TYPE 
                + '&DES_FILE_NAME=' + result.DES_FILE_NAME + '&SRC_FILE_NAME=' + result.SRC_FILE_NAME;
                flag = true;
            }
        }

        var signBtnArea = document.createElement('div');
        var signIconArea = document.createElement('div');
        var signIcon = document.createElement('div');
        var addIconArea = document.createElement('div');
        // addIconArea
        addIconArea.className = 'addIconArea_' + i + ' xi-plus';
        addIconArea.style.setProperty('display', 'flex');
        addIconArea.style.setProperty('justify-content', 'center');
        addIconArea.style.setProperty('align-items', 'center');
        addIconArea.style.setProperty('font-size', '50pt');
        addIconArea.style.width = '115px';
        addIconArea.style.height = '115px';
        addIconArea.style.background = '#0000000f center center / 115px 115px no-repeat';

        // signIcon
        signIcon.className = flag ? 'signIcon_' + i : 'addIcon_' + i;
        signIcon.style.background = 'url(' + imageUrl + ') center center / 100px 100px no-repeat';
        signIcon.style.width = '200px';
        signIcon.style.height = '200px';
        signIcon.style.setProperty('display', 'flex');
        signIcon.style.setProperty('justify-content', 'center');
        signIcon.style.setProperty('align-items', 'center');
        signIcon.style.setProperty('box-shadow', '#D0D0D0 0px 3px 3px 2px');
        if(flag == false){
            signIcon.appendChild(addIconArea);
        }
        // signIconArea
        signIconArea.className = 'signIconArea';
        signIconArea.appendChild(signIcon);
        //signBtnArea
        signBtnArea.className = 'signBtnArea';
        signBtnArea.appendChild(signIconArea);

        var buttonArea = document.createElement('div');
        var buttonSave = document.createElement('div');
        var buttonDelete = document.createElement('div');
        buttonArea.className = 'buttton_area';

        if(flag == true) {
            var saveParam = $.extend(true, {BTN_TYPE: 'SAVE'}, result);
            var deleteParam = $.extend(true, {BTN_TYPE: 'DELETE'}, result);

            btnObj.addButton({"div":buttonArea,"id":"buttonSave_" + i,"text":"{BUTTON.modify}","type":"modify", onclick:onButtonClick.bind(this, saveParam)});
            btnObj.addButton({"div":buttonArea,"id":"buttonDelete_" + i,"text":"{BUTTON.delete}","type":"delete", onclick:onButtonClick.bind(this, deleteParam)});

            buttonArea.appendChild(buttonSave);
            buttonArea.appendChild(buttonDelete);
            signBtnArea.appendChild(buttonArea);
        }

        signAreaWrapper.appendChild(signBtnArea);
    }

    signAreaWrapper.addEventListener('click', function(e) {
        var se = e.srcElement;
        var eventClass = se.className;
        var classSplitBySpace = eventClass.split(' ');
        var classSplit = classSplitBySpace[0].split('_');

        if(classSplit[0] == 'addIcon' || classSplit[0] == 'addIconArea'){
            digitalSignPopupOpen();
        }
    }.bind(this));

    signCol.appendChild(signAreaWrapper);

}, false);


var btnType = params.BTN_TYPE;

if(btnType == 'SAVE'){
    openSavePopup(params);
} else if(btnType == 'DELETE'){
    doDelete(params);
}


Confirm(Sepoa.cache.text.get('CM_010.DELETE_CONFIRM'), function(flag) {
    if(flag == true){
        doServiceAjax('sepoa.svc.contract.SepoaContractDigitalSign', 'TRANSACTION', 'doDelete', params, function(so) {
            if (so.status == 1) {
                Alert(Sepoa.cache.text.get('CM_010.DELETE_SUCCESS'));
                popupCallback();
            } else {
                Alert(so.message);
            }
        });
    }
});
